package com.kovian.finance.snapshot.domain; import jakarta.persistence.*; import java.math.*; import java.time.*; import java.util.*; @Entity @Table(name="financial_snapshots") public class FinancialSnapshot { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @Column(name="owner_id",nullable=false) UUID ownerId; @Column(name="snapshot_date",nullable=false) LocalDate snapshotDate; @Column(name="total_income",nullable=false,precision=19,scale=4) BigDecimal totalIncome; @Column(name="total_expense",nullable=false,precision=19,scale=4) BigDecimal totalExpense; @Column(name="net_cash_flow",nullable=false,precision=19,scale=4) BigDecimal netCashFlow; @Column(name="total_assets",nullable=false,precision=19,scale=4) BigDecimal totalAssets; @Column(name="total_liabilities",nullable=false,precision=19,scale=4) BigDecimal totalLiabilities; @Column(name="net_worth",nullable=false,precision=19,scale=4) BigDecimal netWorth; @Column(name="created_at",nullable=false) OffsetDateTime createdAt=OffsetDateTime.now(); protected FinancialSnapshot(){} public FinancialSnapshot(UUID o,LocalDate d,BigDecimal i,BigDecimal e,BigDecimal a,BigDecimal l){ownerId=o;snapshotDate=d;totalIncome=i;totalExpense=e;netCashFlow=i.subtract(e);totalAssets=a;totalLiabilities=l;netWorth=a.subtract(l);} public void refresh(BigDecimal i,BigDecimal e,BigDecimal a,BigDecimal l){totalIncome=i;totalExpense=e;netCashFlow=i.subtract(e);totalAssets=a;totalLiabilities=l;netWorth=a.subtract(l);} public UUID getId(){return id;} public UUID getOwnerId(){return ownerId;} public LocalDate getSnapshotDate(){return snapshotDate;} public BigDecimal getTotalIncome(){return totalIncome;} public BigDecimal getTotalExpense(){return totalExpense;} public BigDecimal getNetCashFlow(){return netCashFlow;} public BigDecimal getTotalAssets(){return totalAssets;} public BigDecimal getTotalLiabilities(){return totalLiabilities;} public BigDecimal getNetWorth(){return netWorth;} }